 \label{compatibility-definition}
Suppose that $\mathscr{B}, \mathscr{B}' \subseteq \mathbb N \setminus \{1\}$ are any two non-empty collections of integer bases. We call the pair $(\mathscr{B}, \mathscr{B}')$ {\em{compatible}} if 

\begin{equation} b \not\sim b' \text{ for all $(b,b') \in \mathscr{B} \times \mathscr{B}'$,} \; \; \text{and therefore for all $(b, b') \in \overline{\mathscr{B}} \times \overline{\mathscr{B}'}$.} \label{mult-indep-def} \end{equation}

\begin{equation} \label{KS-q2}
{\text{\em{Does $\mathscr N(\mathscr{B}, \mathscr{B}')$ support a Rajchman measure for every compatible pair $(\mathscr{B}, \mathscr{B}')$?}}} 
\end{equation}

A set $E \subseteq [0,1)$ is a {\em{set of uniqueness}} if any complex-valued trigonometric series of the form 
\begin{equation*} 
\sum_{n \in \mathbb Z} a_n e(nx), \qquad e(y) := e^{-2 \pi i y}
\end{equation*} 
that converges to zero on $[0,1) \setminus E$ must be identically zero, i.e. $a_n = 0$ for all $n \in \mathbb Z$.

\begin{equation*} 
\sum_{n \in \mathbb Z} a_n e(nx), \qquad e(y) := e^{-2 \pi i y}
\end{equation*}

 \label{mainthm-2} 
For any non-empty choice of bases $\mathscr{B}' \subseteq \{2, 3, \ldots\}$, there are two collections of probability measures $\mathscr{M}(\mathscr{B}') \subseteq \mathscr{M}^{\ast}(\mathscr{B}')$ on $[0, 1)$ with the following properties. 
\begin{enumerate}[(a)] 
\item For any $\mu \in \mathscr{M}^{\ast}(\mathscr{B}')$, $\mu$-almost every point is non-normal in every base of $\mathscr{B}'$. \label{mainthm-2-parta}
\item For every $\mu \in \mathscr{M}(\mathscr{B}')$ and in the notation of \eqref{NBB'} and \eqref{N4}, 
\begin{equation} \text{$\mu$-almost every point $x$ lies in } \mathscr N(\mathscr{B}, \mathscr{B}'), \quad \text{ where } \mathscr{B} := \{2, 3, \ldots \} \setminus \overline{\mathscr{B}'} \label{normality-seeking-def} \end{equation}   
is the largest collection of bases for which $(\mathscr{B}, \mathscr{B}')$ is a compatible pair. \label{mainthm-2-partb} 
\item For every $\eta > 0$, there exists a measure $\mu_{\eta} \in \mathscr{M}(\mathscr{B}')$ obeying 

 \begin{equation} \label{Frostman-condition} 
 \sup \left\{\frac{\mu_{\eta}([x-r, x+r])}{r^{1 -\eta}} \; \Biggl| \; x \in \mathbb R, r > 0 \right\} < \infty. 
 \end{equation} 
The measure $\mu_{\eta}$ can be chosen to be Rajchman.  \label{mainthm-2-partc} 
 \end{enumerate}

