	For $\eta > 0$, let $\mathtt C_0, \mathtt K_0, \pmb{\Pi}_{\eta}$ be as in the statement of Proposition \ref{Frostman-prop}. Then \eqref{ball-condition-mu} holds for the basic intervals generated in the iterative construction of $\mu$. More precisely, one can find a constant $C_{\eta} = C(\mathtt C_0, \mathtt K_0, \pmb{\Pi}_{\eta}) > 0$ such that  
	\begin{align} \label{ball-condition} 
		\varphi_m(\mathtt I(\mathbf i_m)) = \mathtt w(\mathbf i_m) &\leq C_{\eta} \mathtt s_m^{-\mathtt b_m(1 - \eta)} \quad \text{ for all  } \; \; \mathbf i_m \in \mathbb I_m, \; m \geq 1.   
	\end{align} 
	Here $\mathbb I_m$ is the index set for basic intervals as defined in \eqref{def-I}, whereas $\mathtt w(\mathbf i_m)$ is the weight associated with the  basic interval $\mathtt I(\mathbf i_m)$ as mentioned in \eqref{wt-sum}.

\begin{align} \label{ball-condition} 
		\varphi_m(\mathtt I(\mathbf i_m)) = \mathtt w(\mathbf i_m) &\leq C_{\eta} \mathtt s_m^{-\mathtt b_m(1 - \eta)} \quad \text{ for all  } \; \; \mathbf i_m \in \mathbb I_m, \; m \geq 1.   
	\end{align}


Let us choose the constant $C_{\eta} > 0$ in \eqref{ball-condition} according to the relation   
\begin{equation} \label{define-Ceta}
	\frac{1}{\mathtt N_1} \mathtt r_1^{-(\mathtt b_1-\mathtt a_1)} \leq C_{\eta} \mathtt s_1^{-\mathtt b_1(1 - \eta)}
	\quad \text{ with }\; \mathtt r_1 \; \text{ as in }\; \eqref{rmsm-assumption}.

\end{equation}   

We will prove \eqref{ball-condition} using induction on $m$. Let us start with the base case $m=1$. For any $\mathbf{i}_1 \in \mathbb I_1$, it follows from the mass distribution formula \eqref{second-step-weight}, \eqref{choice-of-theta} and \eqref{define-Ceta} that 

\begin{align*} 
	\mathtt w(\mathbf{i}_1) &\leq \frac{1}{\mathtt N_1} \bigl[\varepsilon_1 \mathtt r_1^{-(\mathtt b_1 - \mathtt a_1)} +  (1 - \varepsilon_1) \mathtt s_1^{-(\mathtt b_1 - \mathtt a_1)} \bigr]  \leq \frac{1}{\mathtt N_1} \times \mathtt r_1^{-(\mathtt b_1 - \mathtt a_1)}  \leq C_{\eta} \mathtt s_1^{-(1 - \eta)}.

\end{align*} 

This concludes the proof of the base case. Let us proceed to the induction step. Suppose that the estimate \eqref{ball-condition} holds for all $1 \leq m \leq k-1$. For any $k\in\mathbb{N}$, the assumption \eqref{s-condition-plus} ensures the existence of some $\mathtt t_k \in \mathscr{C}_0$ and $n_k \in \mathbb{N}$ such that $\mathtt s_k = \mathtt t_k^{n_k}$. Then \eqref{0-and-t-1}, \eqref{s-condition-1} and \eqref{size-Dt} yield 
\begin{equation} \label{skrk-induction} 
\#\bigl[\mathscr{D}_k \bigr] = \mathtt r_k = \bigl( \underline{\mathtt t_k} \bigr)^{n_k}\ \ \text{with}\ \ \underline{\mathtt t_k} := \#\bigl[\mathscr{D} (\mathtt t_k) \bigr], \quad 
\mathtt s_k = \mathtt t_k^{n_k} \leq \mathtt C_0^{n_k} \bigl( \underline{\mathtt t_k} \bigr)^{n_k} = \mathtt C_0^{n_k} \mathtt r_k.  
\end{equation}  
For $\mathbf i_{ k} \in \mathbb I_k$, estimates similar to the base case combined with \eqref{skrk-induction} lead to
\begin{align} 
	\mathtt w(\mathbf i_{ k}) &\leq \Bigl[{\mathtt w(\mathbf i_{k-1})} \times \mathtt N_{k}^{-1} \Bigr] \times \Bigl[\varepsilon_{ k} \mathtt r_{k}^{-(\mathtt b_{ k} - \mathtt a_{ k})} + (1 - \varepsilon_{k}) \mathtt s_{k}^{-(\mathtt b_{k} - \mathtt a_{k})}\Bigr] \nonumber \\ 
	&\leq \mathtt w(\mathbf i_{ k-1}) \times \Bigl[2 {\mathtt s_{k-1}^{\mathtt b_{k-1}}}{\mathtt s_{k}^{-\mathtt a_{k}}} \Bigr] \times \mathtt r_{k}^{-(\mathtt b_{\mathtt k} - \mathtt a_{k})} \nonumber \\ 
	&\leq \Bigl[ C_{\eta} \mathtt s_{k-1}^{-\mathtt b_{k-1}(1 - \eta)} \Bigr] \times \Bigl[ 2 {\mathtt s_{k-1}^{\mathtt b_{k-1}}}{\mathtt s_{k}^{-\mathtt a_{k}}} \Bigr] \times \Bigl[ \mathtt C_0^{n_k(\mathtt b_{k} - \mathtt a_{k})} \mathtt s_{k}^{-(\mathtt b_{k} - \mathtt a_{k})}  \Bigr]  \nonumber = 2C_{\eta} \mathtt C_0^{n_k(\mathtt b_{k} - \mathtt a_{k})} \mathtt s_{k-1}^{\eta \mathtt b_{k-1}} \mathtt s_{k}^{- \mathtt b_{k}} \nonumber \\  
	&\leq C_{\eta} \Bigl[2 \mathtt C_0^{n_k \mathtt b_{k}} \mathtt s_{k}^{-\eta \mathtt b_{k}/2}\Bigr] \times \Bigl[\mathtt s_{k-1}^{ \mathtt b_{k-1}} \mathtt s_{k}^{-\mathtt b_{k}/2} \Bigr]^{\eta} \times  \mathtt s_{k}^{-\mathtt b_{k}(1 - \eta)} \nonumber \\ 
	&\leq C_{\eta} \Bigl[2 \mathtt C_0 {\mathtt t_k^{-\frac{\eta}{2}} }\Bigr]^{\mathtt b_{k}n_k} \times  \mathtt s_{k}^{-\mathtt b_{k}(1 - \eta)}
	\leq C_{\eta} \Bigl[2 \mathtt C_0 \mathtt K_0^{-\frac{\eta}{2}} \Bigr]^{\mathtt b_{k}n_k}   \mathtt s_{k}^{-\mathtt b_{k}(1 - \eta)}  \leq C_{\eta} \mathtt s_{k}^{-\mathtt b_k(1 - \eta)}.  \label{ball-condition-step2}
\end{align}   
The second inequality in the display above uses the relation $\mathtt r_k < \mathtt s_k$ and also 
