\end{align*}  It follows from the mass distribution principle \eqref{mass-wk} that for $\mathtt M \geq m$, 
\begin{align*} \varphi_{\mathtt M}(I) &\leq \sum_{i, k} \bigl\{\varphi_{\mathtt M}\bigl(\mathtt J_k(\mathtt I_i) \bigr): \mathtt J_k(\mathtt I_i) \cap I \neq \emptyset, i = 1, 2  \bigr\} \\ &= \sum_{i, k} \bigl\{\varphi_{m}\bigl(\mathtt J_k(\mathtt I_i) \bigr): \mathtt J_k(\mathtt I_i) \cap I \neq \emptyset, i=1, 2  \bigr\}  \\ &\leq 2 |I| \mathtt s_m^{\mathtt a_m} \mathtt N_m^{-1} \max \bigl\{ \mathtt w(\mathbf i_{m-1}) : \mathbf i_{m-1} \in \mathbb I_{m-1} \bigr\}.
