Since $\mathfrak C$ is an exponential sum over the index set $\mathbb L$ defined in \eqref{step-2-decomp}, let us start with an explicit representation of its summands. Every $\ell \in \mathbb L$ is characterized by a digit vector $\mathtt d = (\mathtt d_0, \ldots, \mathtt d_{\mathtt b-\mathtt a-1}) \in \mathbb Z_{\mathtt s}^{\mathtt b - \mathtt a}$ obeying the relation in \eqref{rep-l-s}. Therefore 

\begin{align*}
e(\xi \ell \mathtt s^{-\mathtt b}) = e \Bigl( \xi \sum_{j=0}^{\mathtt b - \mathtt a-1} \mathtt d_j \mathtt s^{j - \mathtt b}\Bigr) = \prod_{j=0}^{\mathtt b-\mathtt a-1} e \bigl(\xi \mathtt d_j \mathtt s^{j - \mathtt b} \bigr) 
\end{align*} 
for some $\mathbf d = (\mathtt d_0, \ldots, \mathtt d_{\mathtt b-\mathtt a-1}) \in \mathbb Z_{\mathtt s}^{\mathtt b-\mathtt a}$.  As a result, the sum  $\mathfrak C$  decomposes into a product: 






\begin{align} 
\mathtt s^{\mathtt b-\mathtt a} \mathfrak C(\xi) &= \sum_{\mathbf d \in \mathbb Z_{\mathtt s}^{\mathtt b-\mathtt a}} \prod_{j=0}^{\mathtt b-\mathtt a-1} e \bigl(\xi \mathtt d_j \mathtt s^{j - \mathtt b} \bigr) = \prod_{j=0}^{\mathtt b - \mathtt a-1} \Bigl[ \sum_{\mathtt d_j =0}^{\mathtt s-1} e\bigl( \xi \mathtt d_j \mathtt s^{j-\mathtt b} \bigr) \Bigr] =  \prod_{\mathtt k=\mathtt a+1}^{\mathtt b} \Bigl[ \sum_{\mathtt d =0}^{\mathtt s-1}  e\bigl( \xi \mathtt d \mathtt s^{-\mathtt k} \bigr) \Bigr]  \nonumber \\
&= \prod_{\mathtt k=\mathtt a+1}^{\mathtt b} \left[ 1 + e(\xi \mathtt s^{-\mathtt k}) + \ldots + e \bigl(\xi(\mathtt s-1) \mathtt s^{- \mathtt k} \bigr) \right].  \label{C-factor} 
\end{align} 
Each factor occurring in \eqref{C-factor} is a geometric sum, with the $\mathtt k^{\text{th}}$ factor given by 
\begin{equation}   1 + e(\xi \mathtt s^{-\mathtt k}) + \ldots + e \bigl(\xi(\mathtt s-1) \mathtt s^{- \mathtt k} \bigr) = \left\{ \begin{aligned} &\mathtt s &\text{ if } \mathtt s^{\mathtt k} | \xi, \\ &\frac{1 - e(\xi \mathtt s^{-\mathtt k + 1})}{1 - e(\xi \mathtt s^{-\mathtt k})} &\text{ if } \mathtt s^{\mathtt k} \nmid \xi.  \end{aligned} \right\} \label{geometric-sum}  \end{equation} 
Three cases arise. If $\mathtt s^{\mathtt b} \mid \xi$, then each factor of \eqref{C-factor} is $\mathtt s$, which yields $\mathfrak C(\xi) = 1$. If $\mathtt s^{\mathtt a} \nmid \xi$ then inserting \eqref{geometric-sum} into \eqref{C-factor} leads to a telescoping product: 
\[\mathfrak C(\xi) = \mathtt s^{\mathtt a - \mathtt b} \prod_{\mathtt k = \mathtt a+1}^{\mathtt b} \left[ \frac{1 - e(\xi \mathtt s^{-\mathtt k + 1})}{1 - e(\xi \mathtt s^{-\mathtt k})} \right] = \mathtt s^{\mathtt a- \mathtt b} \frac{1 - e(\xi \mathtt s^{-\mathtt a})}{1 - e(\xi \mathtt s^{-\mathtt b})}. \] 
Finally, if $\mathtt s^{\mathtt a} \mid \xi$, $\mathtt s^{\mathtt b} \nmid \xi$ and $\mathtt k_0 \in \{\mathtt a+1, \ldots, \mathtt b\}$ is the smallest integer such that $\mathtt s^{\mathtt k_0} \nmid \xi$, then each factor of \eqref{C-factor} corresponding to $\mathtt k < \mathtt k_0$ equals $\mathtt s$, whereas the factor corresponding to $\mathtt k = \mathtt k_0$ equals zero. Combining all these observations establishes \eqref{C}.

\begin{align*}
e(\xi \ell \mathtt s^{-\mathtt b}) = e \Bigl( \xi \sum_{j=0}^{\mathtt b - \mathtt a-1} \mathtt d_j \mathtt s^{j - \mathtt b}\Bigr) = \prod_{j=0}^{\mathtt b-\mathtt a-1} e \bigl(\xi \mathtt d_j \mathtt s^{j - \mathtt b} \bigr) 
\end{align*}

\begin{align} 
\mathtt s^{\mathtt b-\mathtt a} \mathfrak C(\xi) &= \sum_{\mathbf d \in \mathbb Z_{\mathtt s}^{\mathtt b-\mathtt a}} \prod_{j=0}^{\mathtt b-\mathtt a-1} e \bigl(\xi \mathtt d_j \mathtt s^{j - \mathtt b} \bigr) = \prod_{j=0}^{\mathtt b - \mathtt a-1} \Bigl[ \sum_{\mathtt d_j =0}^{\mathtt s-1} e\bigl( \xi \mathtt d_j \mathtt s^{j-\mathtt b} \bigr) \Bigr] =  \prod_{\mathtt k=\mathtt a+1}^{\mathtt b} \Bigl[ \sum_{\mathtt d =0}^{\mathtt s-1}  e\bigl( \xi \mathtt d \mathtt s^{-\mathtt k} \bigr) \Bigr]  \nonumber \\
&= \prod_{\mathtt k=\mathtt a+1}^{\mathtt b} \left[ 1 + e(\xi \mathtt s^{-\mathtt k}) + \ldots + e \bigl(\xi(\mathtt s-1) \mathtt s^{- \mathtt k} \bigr) \right].  \label{C-factor} 
\end{align}

