 \label{H-lemma}
There exists an absolute constant $C_0 > 0$ with the following property. Let $\mathbf s, \mathbf a, \mathbf b$ be as in \eqref{sabe} and $\mathtt N_2$ as in \eqref{N2}. Then the function $\mathfrak H(\xi)$ given by 
\begin{align} 
&\mathfrak H(\xi) := \frac{1 - e(\xi \mathtt N_2 \mathtt s_2^{-\mathtt a_2})}{1 - e(\xi \mathtt s_1^{-\mathtt b_1})} \quad \text{ obeys } \quad |\mathfrak H (\xi) - 1| \leq C_0 |\xi| \mathtt s_1^{\mathtt b_1} \mathtt s_2^{-\mathtt a_2},  \label{H}  \\ &\text{ provided } \quad \xi \in \mathbb Z, \quad  \mathtt s_1^{\mathtt b_1} \nmid \xi, \quad \text{ and } \quad |\xi|^2 \leq \mathtt s_1^{\mathtt b_1} \mathtt s_2^{\mathtt a_2}. \label{xi-range} 
\end{align}

\begin{align} 
&\mathfrak H(\xi) := \frac{1 - e(\xi \mathtt N_2 \mathtt s_2^{-\mathtt a_2})}{1 - e(\xi \mathtt s_1^{-\mathtt b_1})} \quad \text{ obeys } \quad |\mathfrak H (\xi) - 1| \leq C_0 |\xi| \mathtt s_1^{\mathtt b_1} \mathtt s_2^{-\mathtt a_2},  \label{H}  \\ &\text{ provided } \quad \xi \in \mathbb Z, \quad  \mathtt s_1^{\mathtt b_1} \nmid \xi, \quad \text{ and } \quad |\xi|^2 \leq \mathtt s_1^{\mathtt b_1} \mathtt s_2^{\mathtt a_2}. \label{xi-range} 
\end{align}


For $\mathfrak H$ defined in \eqref{H}, the expression $\mathfrak H - 1$ can  be written as 
\begin{equation} \label{HND}
\mathfrak H(\xi) -  1= \frac{\mathfrak N}{\mathfrak D}, \; \text{ where } \; \mathfrak N := e(\xi \mathtt s_1^{-\mathtt b_1}) - e(\xi \mathtt N_2 \mathtt s_2^{-\mathtt a_2}) \; \text{ and } \; \mathfrak D := 1 - e(\xi \mathtt s_1^{-\mathtt b_1}). 
\end{equation}   
The numerator $\mathfrak N$ is estimated from above, as follows: 
\begin{equation} \label{N-est}  
|\mathfrak N| = \bigl| e \bigl(\xi( \mathtt s_1^{-\mathtt b_1} - \mathtt N_2 \mathtt s_2^{-\mathtt a_2}) \bigr) -1 \bigr| \leq C_0 |\xi| \bigl| \mathtt s_1^{-\mathtt b_1}  - \mathtt N_2 \mathtt s_2^{-\mathtt a_2} \bigr| \leq C_0 |\xi| \mathtt s_2^{-\mathtt a_2}. 
\end{equation}   
The first inequality in \eqref{N-est} follows from the Lipschitz property \eqref{Lipschitz} of the map $t \mapsto e(t)$ on $[-1,1]$. The second inequality is a consequence of the definition \eqref{N2} of $\mathtt N_2$, which says that 
\[ \mathtt s_2^{-\mathtt a_2} \leq \mathtt s_1^{-\mathtt b_1} - \mathtt N_2 \mathtt s_2^{-\mathtt a_2} \leq 2 \mathtt s_2^{-\mathtt a_2}. \]  The range of $\xi$ assumed in \eqref{xi-range} and the size conditions on $\mathtt s_1, \mathtt s_2$ specified in \eqref{sabe} ensure that 
\[ |\xi| \mathtt s_2^{-\mathtt a_2} \leq  \mathtt s_1^{\frac{\mathtt b_1}{2}} \mathtt s_2^{-\frac{\mathtt a_2}{2}} < 1, \]
which justifies this step. 
\vskip0.1in 
\noindent Let us turn now to the denominator $\mathfrak D$ in \eqref{HND}, whose absolute value 
\[ |\mathfrak D| = 2 |\sin(\pi \xi \mathtt s_1^{-\mathtt b_1})| = 2 |\sin \bigl(\pi \{\xi \mathtt s_1^{-\mathtt b_1} \} \bigr)| \]  we bound from below. Here $\{x\} \in [0, 1)$ denotes the fractional part of $x$. Since $\mathtt s_1^{\mathtt b_1} \nmid \xi$, we have $\xi \mathtt s_1^{-\mathtt b_1} \in \mathbb Z + \mathtt s_1^{-\mathtt b_1} \{1, 2, \ldots, \mathtt s_1^{\mathtt b_1}-1\}$. 
In other words, $\{\xi \mathtt s_1^{-\mathtt b_1}\} \in (0, 1)$ is a nonzero integer multiple of $\mathtt s_1^{-\mathtt b_1}$. In view of the monotone increasing nature of the function $t \mapsto |\sin(t)|$ on $[0, \frac{\pi}{2}]$ and its symmetry about $t = \frac{\pi}{2}$, we deduce   
\begin{equation} \label{D-est} 
|\mathfrak D| = 2|\sin(\pi \xi \mathtt s_1^{-\mathtt b_1})| =  2|\sin \bigl(\pi \{\xi \mathtt s_1^{-\mathtt b_1} \} \bigr)| \geq 2|\sin(\pi \mathtt s_1^{-\mathtt b_1})| \geq C_0^{-1} \mathtt s_1^{-\mathtt b_1}.
\end{equation} 
The last step above follows from the relation \eqref{sine} applied with $t = \mathtt s_1^{-\mathtt b_1}$. Combining \eqref{N-est}, \eqref{D-est} with \eqref{HND} leads to the conclusion \eqref{H}.

