\end{align}  
As in the proof of Lemma \ref{single-scale-product-lemma}, the argument henceforth splits into several cases depending on the divisibility of $\xi$ by powers of $\mathtt s_1$. 




\vskip0.1in 
\noindent {\em{Case 1: }} Suppose first $\mathtt s_1^{\mathtt a_1} \mid \xi$ but $\mathtt s_1^{\mathtt b_1} \nmid \xi$. It follows from Lemma \ref{BC-lemma} that in this case $\mathfrak C_1(\xi) = 0$. As a result, \eqref{G2} yields $|\mathfrak G(\xi)| \leq \varepsilon_1$, which is in fact a stronger estimate than the one claimed in \eqref{G-est}. 
\vskip0.1in
\noindent {\em{Case 2: }} Next assume $\mathtt s_1^{\mathtt b_1} \mid \xi$. Then Lemma \ref{A2-lemma} applies to $\mathfrak A_2$, with \eqref{A2} dictating that 
\[ |\mathfrak G| = |\mathfrak B_1| \times |\mathfrak A_2| \leq |\mathfrak A_2| \leq C_0 \mathtt s_1^{\mathtt b_1} \mathtt s_2^{-\mathtt a_2}. \]
This too is stronger than the estimate claimed in \eqref{G-est}.   
\vskip0.1in
\noindent {\em{Case 3: }} Finally suppose that $\mathtt s_1^{\mathtt a_1} \nmid \xi$. Let us consider the product $\mathfrak A_2 \mathfrak C_1$ appearing in \eqref{G2}. It follows from \eqref{def-A} and Lemma \ref{BC-lemma} that 
\begin{align}  |\mathfrak A_2(\xi) \mathfrak C_1(\xi)| &= \frac{\mathtt s_1^{\mathtt a_1-\mathtt b_1}}{\mathtt N_2} \left| \frac{1 - e(\xi \mathtt N_2 \mathtt s_2^{-\mathtt a_2})}{1 - e(\xi \mathtt s_2^{-\mathtt a_2})} \times \frac{1 - e(\xi \mathtt s_1^{-\mathtt a_1})}{1 - e(\xi \mathtt s_1^{-\mathtt b_1})} \right| \nonumber \\ 
&\leq C_0 \frac{\mathtt s_1^{\mathtt a_1}}{\mathtt s_2^{\mathtt a_2}} |\mathfrak H(\xi)| \times |\sin(\pi \xi \mathtt s_2^{-\mathtt a_2})|^{-1} 


\leq C_0 \mathtt s_1^{\mathtt a_1} |\xi|^{-1}. \label{case2} 
\end{align} 
Here $\mathfrak H(\xi)$ is the function defined in \eqref{H}. The first inequality of the display above follows from the trivial bound 
\[ |1 - e(\xi \mathtt s_1^{-\mathtt a_1})| \leq 2 \quad \text{ and the estimate } \quad \mathtt N_2 \geq \frac{1}{2} \mathtt s_2^{\mathtt a_2} \mathtt s_1^{-\mathtt b_1}, \] which in turn is a consequence of \eqref{N2}. The last inequality in \eqref{case2} involves two separate estimates: the first factor $\mathfrak H$ is estimated using the bound \eqref{s-new} from Corollary \ref{H-cor}. The assumption $\mathtt s_1^{\mathtt a_1} \nmid \xi$ ensures $\mathtt s_1^{\mathtt b_1} \nmid \xi$ as well; further, the choice of $\xi$ in \eqref{G-est} meets the requirements in \eqref{xi-range}, permitting the application of the corollary. The second factor $\sin(\pi \xi \mathtt s_2^{-\mathtt a_2})$ is estimated using the lower bound \eqref{sine} on the sine function, based on the observation that any $\xi$ in the range given in \eqref{G-est} obeys $|\xi| < \frac{1}{2} \mathtt s_2^{\mathtt a_2}$. Substituting the estimate in \eqref{case2} into \eqref{G2} yields an upper bound for $|\mathfrak G|$ that is consistent with \eqref{G-est}. This completes the analysis of all three cases, and concludes the proof.

