\underline{\mathfrak w}_1(\xi) &:=  \varepsilon \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) \Bigl[ \mathfrak B^{\ast}(\xi) - 1 \Bigr], \quad \underline{\mathfrak w}_2(\xi) := \varepsilon \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) \Bigl[  1 - \mathfrak C(\xi) \Bigr], \label{def-w1w2}
\end{align}


The second equality in \eqref{wm-alternate} is a direct consequence of the first, with the given definitions of $\underline{\mathfrak w}_1, \underline{\mathfrak w}_2$ in \eqref{def-w1w2}. It suffices therefore to just prove the first identity. Combining the definition \eqref{def-wm} of $\mathfrak w$ with the expression \eqref{def-B} for $\mathfrak B$, we find that 
\[ \mathfrak w(\xi) = \varepsilon \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) \Bigl[ \mathfrak B^{\ast}(\xi) - \mathfrak C(\xi) \Bigr] + \Bigl[ \mathfrak C(\xi) \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) - \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt a})\Bigr], \]
where $\mathfrak B^{\ast}$ and $\mathfrak C$ are defined in \eqref{B*C}. The right hand side of the display above is a sum of two terms, the first of which coincides with the claimed expression for $\mathfrak w$ in \eqref{wm-alternate}. The desired formula \eqref{wm-alternate} for $\mathfrak w$ thus follows from the claim that the second term is zero, namely
\begin{equation} 
\mathfrak C(\xi) \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) - \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt a}) \equiv 0 \quad \text{ for all } \xi \in \mathbb Z.  \label{second-term-zero-claim}
\end{equation}
\noindent Lemma \ref{BC-lemma} provides a closed-form expression for $\mathfrak C(\xi)$ in three mutually exclusive and exhaustive scenarios depending on the divisibility properties of $\xi$ in terms of powers of $\mathtt s$.  

We will verify the claim \eqref{second-term-zero-claim} in each of these three cases. 
\begin{itemize} 
\item First suppose that $\mathtt s^{\mathtt b} \mid \xi$. It follows from the expression \eqref{1-hat} for $\widehat{\mathtt 1}$ that $\widehat{1}(\xi \mathtt s^{-\mathtt b}) =  \widehat{1}(\xi \mathtt s^{-\mathtt a}) = 0$ since $\mathtt a < \mathtt b$. Therefore each term in the left hand side of \eqref{second-term-zero-claim} vanishes.
\item Next suppose that  $\mathtt s^{\mathtt a} \mid \xi$, but $\mathtt s^{\mathtt b} \nmid \xi$. Then $\widehat{1}(\xi \mathtt s^{-\mathtt a}) = 0$ from \eqref{1-hat}, whereas $\mathfrak C(\xi) = 0$ from \eqref{C} in Lemma \ref{BC-lemma}. Once again, each term on the left side of \eqref{second-term-zero-claim} vanishes. 
\item Finally, let $\mathtt s^{\mathtt a} \nmid \xi$. Then we obtain from \eqref{C} in Lemma \ref{BC-lemma} that
\begin{align*} 
\mathfrak C(\xi) \times \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) &= \Bigl[\mathtt s^{\mathtt a - \mathtt b} \frac{1 - e(\xi \mathtt s^{-\mathtt a})}{1 - e(\xi \mathtt s^{- \mathtt b})} \Bigr] \times \Bigl[\frac{1 - e \bigl(\xi \mathtt s^{-\mathtt b}\bigr)}{2 \pi i \xi \mathtt s^{-\mathtt b}} \Bigr] \\
&= \frac{1 - e(\xi \mathtt s^{-\mathtt a})}{2 \pi i \xi \mathtt s^{-\mathtt a}} = \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt a}).
\end{align*}
\end{itemize}
This concludes the proof of the claim \eqref{second-term-zero-claim}, and therefore the proof of the lemma.

\begin{equation} 
\mathfrak C(\xi) \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) - \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt a}) \equiv 0 \quad \text{ for all } \xi \in \mathbb Z.  \label{second-term-zero-claim}
\end{equation}

\begin{align*} 
\mathfrak C(\xi) \times \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) &= \Bigl[\mathtt s^{\mathtt a - \mathtt b} \frac{1 - e(\xi \mathtt s^{-\mathtt a})}{1 - e(\xi \mathtt s^{- \mathtt b})} \Bigr] \times \Bigl[\frac{1 - e \bigl(\xi \mathtt s^{-\mathtt b}\bigr)}{2 \pi i \xi \mathtt s^{-\mathtt b}} \Bigr] \\
&= \frac{1 - e(\xi \mathtt s^{-\mathtt a})}{2 \pi i \xi \mathtt s^{-\mathtt a}} = \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt a}).
\end{align*}

\begin{align} 
\mathfrak B^{\ast}(\xi) &= \mathtt r^{\mathtt a - \mathtt b} \sum_{\mathbf d \in \mathscr{D}^{\mathtt b -\mathtt a}} e \Bigl[ \frac{\xi}{\mathtt s^{\mathtt b}} \sum_{j=0}^{\mathtt b- \mathtt a -1} \mathtt d_j \mathtt s^j \Bigr] \nonumber \\ &= \mathtt r^{\mathtt a - \mathtt b}\prod_{j=0}^{\mathtt b -\mathtt a -1} \Bigl[ \sum_{\mathtt d \in \mathscr{D}} e\Bigl(\xi \mathtt d \mathtt s^{j - \mathtt b} \Bigr) \Bigr]  = \prod_{j= \mathtt a +1}^{\mathtt b} \mathfrak g(\xi, j; \mathtt s, \mathscr{D}), \; \text{ where } \label{B*-rep} \\  \mathfrak g(\xi, j) &= \mathfrak g(\xi, j ; \mathtt s,  \mathscr{A} ) := \frac{1}{\#( \mathscr{A} )}\sum_{\mathtt d \in  \mathscr{A} } e\bigl(\xi \mathtt d \mathtt s^{-j} \bigr) \; \text{ for }  \mathscr{A}  \subseteq  \mathbb Z_{\mathtt s}, \; j \in \mathbb N. \label{exp-sum-g-def} 
\end{align}

 \label{(B*-1)-lemma}
There exists an absolute constant $C_0 > 0$ for which the function $\underline{\mathfrak w}_1$ given by \eqref{def-w1w2}




obeys the following estimate uniformly in $\varepsilon\in (0,1)$:  
 \begin{equation} \label{(B*-1)-estimate}
\bigl| \underline{\mathfrak w}_1(\xi) \bigr| \leq C_0 \min \Bigl[1, \frac{\mathtt s^{\mathtt b}}{|\xi|}\Bigr] \times \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}\Bigr],\; \xi \in \mathbb{Z}. 
 \end{equation}

\begin{equation} \label{(B*-1)-estimate}
\bigl| \underline{\mathfrak w}_1(\xi) \bigr| \leq C_0 \min \Bigl[1, \frac{\mathtt s^{\mathtt b}}{|\xi|}\Bigr] \times \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}\Bigr],\; \xi \in \mathbb{Z}. 
 \end{equation}

\begin{equation} \label{w1-preliminary-estimate}
\bigl| \underline{\mathfrak w}_1(\xi)\bigr| \leq  \bigl| \widehat{1}(\xi \mathtt s^{-\mathtt b}) \bigr| \times |\mathfrak B^{\ast}(\xi) - 1|, \quad \text{ uniformly in } \varepsilon\in(0,1). 
\end{equation}

\begin{align} 
\bigl|\mathfrak B^{\ast}(\xi) - 1 \bigr|  &= \Bigl| \Bigl[\mathfrak g(\xi, \mathtt a+1) - 1\Bigr] + \sum_{k = \mathtt a+1}^{\mathtt b -1} \Bigl[ \prod_{j=\mathtt a+1}^{k+1} \mathfrak g(\xi, j) - \prod_{j=\mathtt a+1}^{k} \mathfrak g(\xi, j) \Bigr] \Bigr| \nonumber \\  
&\leq  \bigl|\mathfrak g(\xi, \mathtt a+1) - 1\bigr| +   \sum_{k = \mathtt a+1}^{\mathtt b -1} \bigl|\mathfrak g(\xi, k+1) - 1\bigr| = \sum_{k=\mathtt a}^{\mathtt b} \bigl| \mathfrak g(\xi, k) -1 \bigr| \nonumber \\
&\leq |\xi| \sum_{k = \mathtt a+1}^{\mathtt b} \mathtt s^{-(k-1)} \leq C_0 |\xi| \mathtt s^{-\mathtt a}. \label{B*-1-final}
\end{align}

 \label{1-hat-C-corollary}
There exists an absolute constant $C_0 > 0$ such that 

the following estimate holds uniformly in $\varepsilon\in (0,1)$:
\begin{equation} \label{1-hat-C} 
\bigl| \underline{\mathfrak w}_2(\xi) \bigr| \leq \bigl|\widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) \bigr| \times \bigl|\mathfrak C(\xi) - 1\bigr| \leq C_0 \min \left[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|} \right],\; \xi \in \mathbb{Z}.
\end{equation}

\begin{equation} \label{1-hat-C} 
\bigl| \underline{\mathfrak w}_2(\xi) \bigr| \leq \bigl|\widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) \bigr| \times \bigl|\mathfrak C(\xi) - 1\bigr| \leq C_0 \min \left[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|} \right],\; \xi \in \mathbb{Z}.
\end{equation}

\begin{align*} 
\bigl|\widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b}) \bigr| \times \bigl|\mathfrak C(\xi) - 1\bigr| &= \left| \frac{1 - e(\xi \mathtt s^{-\mathtt b})}{2 \pi i \xi \mathtt s^{-\mathtt b}}\right| \times \left| \mathtt s^{\mathtt a - \mathtt b} \frac{1 - e(\xi \mathtt s^{-\mathtt a})}{1 - e(\xi \mathtt s^{-\mathtt b})} - 1 \right| \\ 
&= \Bigl| \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt a}) - \widehat{\mathtt 1}(\xi \mathtt s^{-\mathtt b})\Bigr|  \leq C_0 \min \left[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}\right] \times \min \Bigl[1, \frac{\mathtt s^{\mathtt b}}{|\xi|} \Bigr] \\
&\leq C_0 \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|} \Bigr].
\end{align*}

 \label{v-lemma} 
There exists an absolute constant $C_0 > 0$ such that the function $\mathtt v$ given by \eqref{uv-def} (or \eqref{identity}) obeys the estimate:

\begin{equation} \label{v-pointwise-estimate}
\bigl| \mathtt v(\xi) \bigr| \leq \bigl|\mathfrak w(\xi) \bigr| 
\leq C_0 \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|}\Bigr],\; \xi\in\mathbb{Z}.
\end{equation}

\begin{equation} \label{v-pointwise-estimate}
\bigl| \mathtt v(\xi) \bigr| \leq \bigl|\mathfrak w(\xi) \bigr| 
\leq C_0 \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|}\Bigr],\; \xi\in\mathbb{Z}.
\end{equation}

\begin{align*} 
 \bigl|\mathfrak w(\xi)  \bigr| & \leq \bigl| \underline{\mathfrak w}_1(\xi) \bigr| + \bigl|\underline{\mathfrak w}_2(\xi)  \bigr| \\ 


&\leq C_0  \min \Bigl[1, \frac{\mathtt s^{\mathtt b}}{|\xi|}\Bigr] \times \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}\Bigr] + C_0 \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|} \Bigr] \\ 
&\leq C_0 \min \Bigl[1, \frac{|\xi|}{\mathtt s^{\mathtt a}}, \frac{\mathtt s^{\mathtt b}}{|\xi|} \Bigr],
\end{align*}

 \label{vm-est-lemma}
There is an absolute constant $C_0 > 0$ such that for any choice of parameters $\pmb{\Pi}$ obeying \ref{param-seq}, 
\eqref{abs} and \eqref{rmsm-assumption}, 
\begin{equation} \label{vm-pointwise-estimate} 
\bigl| \mathtt v_m(\xi) \bigr| \leq C_0 \min \left[1, \frac{|\xi|}{\mathtt s_m^{\mathtt a_m}}, \frac{\mathtt s_m^{\mathtt b_m}}{|\xi|}\right], \quad m \geq 1, \; \xi \in \mathbb Z.   
\end{equation}

\begin{equation} \label{vm-pointwise-estimate} 
\bigl| \mathtt v_m(\xi) \bigr| \leq C_0 \min \left[1, \frac{|\xi|}{\mathtt s_m^{\mathtt a_m}}, \frac{\mathtt s_m^{\mathtt b_m}}{|\xi|}\right], \quad m \geq 1, \; \xi \in \mathbb Z.   
\end{equation}

\begin{equation} \label{Vm-decomposition} 
\mathbb V := \bigl\{(u, v, N) : (u, v) \in \mathbb Z_N^2, \; N \in \mathbb N \bigr\} = \mathbb V_1 \sqcup \mathbb V_2, \text{ with } \mathcal V_m = \mathcal V_{m1} + \mathcal V_{m2} 
\end{equation}

\begin{align} 
\mathbb V_1 := \bigcup_{j=1}^{4} \mathbb V_{1j}, \; &\text{ so that the sum $\mathcal V_{m1}$ can be estimated as } \;  \mathcal V_{m1} \leq \sum_{j=1}^{4} \mathcal W_j, \text{ where } \label{sum-of-W} \\ \mathcal W_{j} &:= \sum \Bigl\{\frac{1}{N^3}|\mathtt v_m(h b^u(b^v-1))| : (u, v, N) \in \mathbb V_{1j} \Bigr\}.
\label{Wj} \end{align}

\begin{align} 
\mathbb V_{11} &:= \bigl\{(u, v, N) \in \mathbb V: b^{u+v} \leq \mathtt s_m^{\frac{\mathtt a_m}{2}}\bigr\}, \; 
\mathbb V_{12} := \bigl\{(u, v, N) \in \mathbb V : b^{u+v} \geq m^2 \mathtt s_m^{\mathtt b_m}\bigr\}, \nonumber\\
\mathbb V_{13} &:=  \bigl\{(u, v, N) \in \mathbb V : N \leq \frac{\mathtt a_m}{4} \log_{b} (\mathtt s_m) \bigr\}, \nonumber\\
\mathbb V_{14} &:= \bigl\{ (u, v, N) \in \mathbb V : N \geq m \mathtt b_m \log_{b} (\mathtt s_m) \bigr\}.
\end{align}

\begin{align} 
\mathcal V_{m2} &= \mathcal V_{m2}(h, b) := \sum \Bigl\{\frac{1}{N^{3}} \bigl| \mathtt v_m \bigl(h b^u(b^v-1)\bigr) \bigr| : (u, v, N) \in \mathbb V_2 \Bigr\}, \text{ where } \label{Vm2-sum-definition} \\  
\mathbb V_2 &:= \left\{(u, v, N) \in \mathbb V \; \Biggl| \; \begin{aligned} &\mathtt s_m^{\frac{\mathtt a_m}{2}} < b^{u+v} < m^2 \mathtt s_m^{\mathtt b_m}, \text{ and } \\  
& \frac{\mathtt a_m}{4} \log_{b} (\mathtt s_m) < N < m \mathtt b_m \log_{b} (\mathtt s_m)
\end{aligned}  \right\}. \label{def-collection-V2}
\end{align}

 \label{W-sum-prop}
Let $\pmb{\Pi}$ be any choice of parameters obeying \eqref{param-seq}, \eqref{abs} and \eqref{rmsm-assumption}. Then for any $h \in \mathbb Z \setminus \{0\}$, $b \in \mathbb N \setminus \{1\}$, there exists a sequence $\{\mathtt c_m(h, b) : m \geq 1\} \subseteq (0, \infty)$ such that   
 \begin{equation} \label{W-sum-estimate}
 \mathcal V_{m1} \leq \sum_{j=1}^{4} \mathcal W_j \leq \mathtt c_m(h, b) \; \; \text{ for all } m \geq 1, \quad\text{with}\; \;  \sum_{m=1}^{\infty} \mathtt c_m(h, b) < \infty. 
 \end{equation}

\begin{equation} \label{W-sum-estimate}
 \mathcal V_{m1} \leq \sum_{j=1}^{4} \mathcal W_j \leq \mathtt c_m(h, b) \; \; \text{ for all } m \geq 1, \quad\text{with}\; \;  \sum_{m=1}^{\infty} \mathtt c_m(h, b) < \infty. 
 \end{equation}

 \label{V2-sum-prop}
Suppose that exactly one of the following assumptions is true. 
\begin{enumerate}[(a)] 
\item The parameter $\pmb{\Pi}$ obeys the hypotheses of Proposition \ref{normality-special-prop}, and  

the base $b$ lies in $\mathscr{B}_1$, the collection of bases given by \eqref{bases-B1-def}. \label{V2-sum-prop-parta}

\item  The parameter $\pmb{\Pi}$ obeys the hypotheses of Proposition \ref{normal-prop}, 

and the base $b$ lies in $\mathscr{B}$, the collection of bases given by \eqref{bases-BC-bar}. \label{V2-sum-prop-partb}
\end{enumerate} 
For each pair $(\pmb{\Pi}, b)$ obeying either \eqref{V2-sum-prop-parta} or \eqref{V2-sum-prop-partb} above, and any $h \in \mathbb Z \setminus \{0\}$, there exists a sequence $\{\mathtt c_m(h, b) : m \geq 1\} \subseteq (0, \infty)$ for which the sum $\mathcal V_{m2}$ given by \eqref{Vm2-sum-definition} satisfies the conclusion
\begin{equation} \label{V2-sum-estimate}
\mathcal V_{m2}(h, b) \leq \mathtt c_m(h, b) \; \; \text{ for all } m \geq 1, \; \; \text{ with } \; \; \sum_{m=1}^{\infty} \mathtt c_m(h, b) < \infty.  
\end{equation}

\begin{equation} \label{V2-sum-estimate}
\mathcal V_{m2}(h, b) \leq \mathtt c_m(h, b) \; \; \text{ for all } m \geq 1, \; \; \text{ with } \; \; \sum_{m=1}^{\infty} \mathtt c_m(h, b) < \infty.  
\end{equation}

For $\pmb{\Pi}, h, b$ as in Proposition \ref{W-sum-prop}, there is a constant $C(\pmb{\Pi}, h, b) > 0$ for which the sums $\mathcal W_1$, $\mathcal W_3$ defined in \eqref{Wj} obey the estimate
\begin{equation} \label{W1W3-bound} 
\mathcal W_1 + \mathcal W_3 \leq C(\pmb{\Pi}, h, b) \mathtt s_m^{-\frac{\mathtt a_m}{2}} \leq C(\pmb{\Pi}, h, b) 2^{-\frac{m}{2}}.
\end{equation} 
The last inequality of \eqref{W1W3-bound} follows from the assumption $2\mathtt s_m^{\mathtt a_m} < 2\mathtt s_m^{\mathtt b_m} \leq \mathtt s_{m+1}^{\mathtt a_{m+1}}$ ensured by \eqref{abs}.

\begin{equation} \label{W1W3-bound} 
\mathcal W_1 + \mathcal W_3 \leq C(\pmb{\Pi}, h, b) \mathtt s_m^{-\frac{\mathtt a_m}{2}} \leq C(\pmb{\Pi}, h, b) 2^{-\frac{m}{2}}.
\end{equation}


The procedure for estimating $\mathcal W_1 + \mathcal W_3$ is similar to the estimation of $\mathscr{U}_{m1}$ in Proposition \ref{U-prop}. We use the pointwise upper bound $|\xi| \mathtt s_m^{-\mathtt a_m}$ on $\mathtt v_m(\xi)$ provided by \eqref{vm-pointwise-estimate}:

\begin{align} 
\mathcal W_1 + \mathcal W_3 &= \sum \Bigl\{ \frac{1}{N^{3}} \bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| : (u, v) \in \mathbb V_{11} \cup \mathbb V_{13} \Bigr\} \nonumber \\  &\leq C_0 \sum \left\{\frac{1}{N^{3}} \frac{|h b^u(b^v-1)|}{\mathtt s_m^{\mathtt a_m}} : \mathbb V_{11} \cup \mathbb V_{13} \right\}. \label{w1+w3-step1}
\end{align} 
We observe the following property of the indices $(u, v, N) \in \mathbb V_{11} \cup \mathbb V_{13}$:
\[b^{u+v} \leq \begin{cases} \mathtt s_m^{\frac{\mathtt a_m}{2}} \; \; \text{ by definition }  &\text{ on } \mathbb V_{11} \\ b^{2N} \leq b^{\frac{\mathtt a_m}{2}  \log_{\mathtt b} (\mathtt s_m) } = \mathtt s_m^{\frac{\mathtt a_m}{2}} &\text{ on } \mathbb V_{13}. \end{cases} \] 
Substituting this into the bound \eqref{w1+w3-step1} for the sum above, we find that
\begin{align*} 
\mathcal W_1 + \mathcal W_3 &\leq 2 \mathtt s_m^{-\mathtt a_m} \sum \Bigl\{\frac{1}{N^3}|h| b^{u+v} : b^{u+v} \leq \mathtt s_m^{\frac{\mathtt a_m}{2}}, (u, v) \in \mathbb Z_N^2, N \in \mathbb N \Bigr\} \\ &\leq C(h)  \mathtt s_m^{-\mathtt a_m} \sum_{N=1}^{\infty} N^{-3} \sum_{u=1}^{N} \sum_r \left\{b^r : 1 \leq b^r \leq \mathtt s_m^{\frac{\mathtt a_m}{2}} \right\} \\ &\leq C(h, b) \mathtt s_m^{-\mathtt a_m} \mathtt s_m^{\frac{\mathtt a_m}{2}} \sum_{N=1}^{\infty} N^{-2} \leq C(h, b)  \mathtt s_m^{-\frac{\mathtt a_m}{2}}. 
\end{align*} 
The second inequality is a consequence of a change of variables $(u, v) \mapsto (u, r)$, with $r = u+v$. This is the claimed inequality \eqref{W1W3-bound}

\begin{align} 
\mathcal W_1 + \mathcal W_3 &= \sum \Bigl\{ \frac{1}{N^{3}} \bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| : (u, v) \in \mathbb V_{11} \cup \mathbb V_{13} \Bigr\} \nonumber \\  &\leq C_0 \sum \left\{\frac{1}{N^{3}} \frac{|h b^u(b^v-1)|}{\mathtt s_m^{\mathtt a_m}} : \mathbb V_{11} \cup \mathbb V_{13} \right\}. \label{w1+w3-step1}
\end{align}

\begin{align*} 
\mathcal W_1 + \mathcal W_3 &\leq 2 \mathtt s_m^{-\mathtt a_m} \sum \Bigl\{\frac{1}{N^3}|h| b^{u+v} : b^{u+v} \leq \mathtt s_m^{\frac{\mathtt a_m}{2}}, (u, v) \in \mathbb Z_N^2, N \in \mathbb N \Bigr\} \\ &\leq C(h)  \mathtt s_m^{-\mathtt a_m} \sum_{N=1}^{\infty} N^{-3} \sum_{u=1}^{N} \sum_r \left\{b^r : 1 \leq b^r \leq \mathtt s_m^{\frac{\mathtt a_m}{2}} \right\} \\ &\leq C(h, b) \mathtt s_m^{-\mathtt a_m} \mathtt s_m^{\frac{\mathtt a_m}{2}} \sum_{N=1}^{\infty} N^{-2} \leq C(h, b)  \mathtt s_m^{-\frac{\mathtt a_m}{2}}. 
\end{align*}


For $\pmb{\Pi}, h, b$ as in Proposition \ref{W-sum-prop}, there is a constant $C(\pmb{\Pi}, h, b) > 0$ for which the sums $\mathcal W_2$ and $\mathcal W_4$ defined in \eqref{Wj} obey the estimate
\begin{equation} 
\mathcal W_2 + \mathcal W_4 \leq C(h, b) m^{-2} \quad \text{for all}\;m \geq 4. \label{W2W4-bound}
\end{equation} 
Thus $\mathcal W_2 + \mathcal W_4$ is dominated by a term that is summable in $m$.

\begin{equation} 
\mathcal W_2 + \mathcal W_4 \leq C(h, b) m^{-2} \quad \text{for all}\;m \geq 4. \label{W2W4-bound}
\end{equation}


The quantity $\mathcal W_2$ is handled in a way simiilar to $\mathcal W_1$ and $\mathcal W_3$, except here we use the bound $|\mathtt v_m(\xi)| \leq C_0 \mathtt s_m^{\mathtt b_m}/|\xi|$ from \eqref{vm-pointwise-estimate}:  
\begin{align} 
\mathcal W_2 &= \sum \Bigl\{ \frac{1}{N^3}\bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| : (u, v) \in \mathbb V_{12} \Bigr\} \nonumber  \\ 
&\leq C_0  \sum \Bigl\{ \frac{1}{N^{3}} \frac{\mathtt s_m^{\mathtt b_m}}{|h b^u(b^v-1)|}  : (u, v) \in \mathbb V_{12} \Bigr\} \nonumber \\
&\leq C_0 \mathtt s_m^{\mathtt b_m}  \sum \Bigl\{ \frac{1}{N^{3} |h| b^{u+v}} : b^{u+v} \geq m^2 \mathtt s_m^{{\mathtt b_m}}, (u, v) \in \mathbb Z_N^2, N\in\mathbb{N} \Bigr\} \nonumber \\ 
&\leq C(h) \mathtt s_m^{\mathtt b_m} \sum_{N=1}^{\infty} N^{-3} \sum_{u=1}^{N} \sum_r \left\{b^{-r} : b^r \geq m^2 \mathtt s_m^{\mathtt b_m} \right\} \nonumber \\ 
&\leq C(h, b) \mathtt s_m^{\mathtt b_m} m^{-2} \mathtt s_m^{-\mathtt b_m} \sum_{N=1}^{\infty} N^{-2} \leq C(h, b) m^{-2}. \label{W2} 
\end{align}
The quantity $\mathcal W_4$ is analyzed in a different way. In view of the already obtained bounds on $\mathcal W_1$ and $\mathcal W_2$,  it suffices to only bound the quantity $\mathcal W_4^{\ast}$, the sum of $|\mathtt v_m(h b^u (b^v-1))|/N^3$ on
\[ \mathbb V_{14}^{\ast} := \bigl\{(u, v, N) \in \mathbb V_{14} : \mathtt s_m^{\frac{\mathtt a_m}{2}} \leq b^{u+v} \leq m^2 \mathtt s_m^{\mathtt b_m}\bigr\}, \]
since $|\mathcal W_4 - \mathcal W_4^{\ast}|$ is bounded above by at most a constant multiple of $\mathcal W_1 + \mathcal W_2$. 
On $\mathbb V_{14}^{\ast}$, the indices $(u, v)$ satisfy the relation
\begin{equation}  \max(u, v) \leq u + v \leq \log_b\bigl(m^2 \mathtt s_m^{\mathtt b_m}\bigr) \leq 2 \mathtt b_m \log_b (\mathtt s_m). \label{uv-max} \end{equation} 
The last inequality follows from \eqref{abs}, which implies \[ m^2 \leq 2^{m} \leq \mathtt s_m^{\mathtt b_m} \quad \text{ for all } m \geq 4,  \] since $2\mathtt s_m^{\mathtt b_m} \leq \mathtt s_{m+1}^{\mathtt a_{m+1}} <\mathtt s_{m+1}^{\mathtt b_{m+1} }$ and $\mathtt s_{0}^{\mathtt b_{0} } = 1$. Combining the bound \eqref{uv-max} on $u, v$ with the trivial bound $|\mathtt v_m| \leq 1$ from \eqref{vm-pointwise-estimate}, we obtain 
\begin{align} 
\mathcal W_4^{\ast} &\leq \sum \Bigl\{\frac{1}{N^3}|\mathtt v_m \bigl(hb^u(b^v-1) \bigr)| : (u, v, N) \in \mathbb V_{14}^{\ast}  \Bigr\} \nonumber \\
&\leq \sum \Bigl\{\frac{1}{N^3} : u, v \leq 2\mathtt b_m \log_b (\mathtt s_m), \;  N \geq m \mathtt b_m \log_b (\mathtt s_m) \Bigr\} \nonumber \\ 
&\leq \sum \Bigl\{ \frac{1}{N^3}  \bigl(2\mathtt b_m \log_b (\mathtt s_m) \bigr)^2 : N \geq m \mathtt b_m \log_b (\mathtt s_m) \Bigr\} \nonumber \\
&\leq C_0  \bigl( \mathtt b_m \log_b (\mathtt s_m) \bigr)^2 \bigl(  m \mathtt b_m \log_b (\mathtt s_m) \bigr)^{-2} \leq C_0 m^{-2}.  \label{W4}
\end{align}    
Combining \eqref{W2} and \eqref{W4} leads to \eqref{W2W4-bound}.

\begin{align} 
