Let $\pmb{\Pi}$ be a choice of parameters {as in Proposition \ref{V2-sum-prop} \eqref{V2-sum-prop-partb}}, and let $\mathscr{B}$ be the choice of bases given in Proposition \ref{normal-prop}. Then for every base $b \in \mathscr{B}$ and every $h \in \mathbb Z \setminus \{0\}$,  there exist positive constants $c, C$ depending only on $h, b, \pmb{\Pi}$ such that the following inequalities hold.
\begin{equation} \label{Y1+Y2+Y3+Y4}
\mathcal Y_1 + \mathcal Y_2 + \mathcal Y_3  \leq C(h,b, \pmb{\Pi}) 2^{-c \mathtt K_m^2}, \qquad \mathcal Y_4 \leq C(h,b, \pmb{\Pi}) 2^{-c\mathtt K_m}.
\end{equation}

\begin{equation} \label{Y1+Y2+Y3+Y4}
\mathcal Y_1 + \mathcal Y_2 + \mathcal Y_3  \leq C(h,b, \pmb{\Pi}) 2^{-c \mathtt K_m^2}, \qquad \mathcal Y_4 \leq C(h,b, \pmb{\Pi}) 2^{-c\mathtt K_m}.
\end{equation}

\begin{align} 
\mathcal Y_1 &\leq \sum_{u, v, N} \Biggl\{\frac{1}{N^3}\bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| \; \; \Biggl| \; \; \begin{aligned} &\mathtt k(\mathtt u) + \mathtt h = \lfloor u\tau_m \rfloor + \mathtt h \leq  \mathtt K_m, \; v\in \mathbb Z_N, \\  &\frac{\mathtt a_m}{4} \log_b (\mathtt s_m) < N < m\mathtt b_m \log_b (\mathtt s_m) \end{aligned} \Biggr\} \nonumber \\
&\leq C_0 \sum_{N} \Bigl\{\frac{\mathtt K_m}{\tau_m N^2} :  \frac{\mathtt a_m}{4} \log_b (\mathtt s_m) < N < m\mathtt b_m \log_b (\mathtt s_m) \Bigr\} \label{Y1-initial} \\ 
&\leq C_0 \frac{\mathtt K_m}{\tau_m \mathtt a_m \log_b (\mathtt s_m)}   = C_0 \mathtt K_m \mathtt s_m^{-\mathtt K_m^2} \frac{\sigma_{1m}}{\beta_{1m}} \frac{1}{\log_b (\mathtt s_m)} \; \; (\text{using \eqref{what-is-taum} and}\ \mathtt a_m=\mathtt s_m^{\mathtt K_m^2})\nonumber \\
&\leq C_0 \mathtt K_m \mathtt s_m^{-\mathtt K_m^2} \frac{\log_2 (\mathtt s_m)}{\log_b (\mathtt s_m)} \leq C(b) \mathtt K_m \mathtt s_m^{-\mathtt K_m^2} \leq C(b, \pmb{\Pi}) 2^{-c_0 \mathtt K_m^2} \text{ for some } c_0 > 0. \label{Y1-final}
\end{align}

Let us write  
\begin{equation} \mathcal Y_2 = \mathcal Y_{2}' + \mathcal Y_{2}''; \label{Y2-decomp} \end{equation} 
the sum $\mathcal Y_2'$ ranges over the subset of $\overline{\mathbb V}_{22}$ where $\mathtt b_m - R \leq \mathtt k(u) + \mathtt h \le \mathtt b_m$.

\begin{align} 
\mathcal Y_{2}' & \leq \sum_{u, v, N} \Biggl\{\frac{1}{N^3}\bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| \; \; \Biggl| \; \; \begin{aligned} & \mathtt b_m - R \leq \mathtt k(u) + \mathtt h \leq  \mathtt b_m, \; v \in \mathbb Z_N, \\  &\frac{\mathtt a_m}{4} \log_b (\mathtt s_m) < N  \end{aligned} \Biggr\} \nonumber \\ 
&\leq \sum_{u, v, N} \Biggl\{\frac{1}{N^3}\bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| \; \; \Biggl| \; \; \begin{aligned} & \mathtt b_m - R \leq u\tau_m + \mathtt h \leq  \mathtt b_m + 1, \; v \in \mathbb Z_N, \\  &\frac{\mathtt a_m}{4} \log_b (\mathtt s_m) < N  \end{aligned} \Biggr\} \nonumber \\
&\leq C_0 \sum_N \Bigl\{\frac{R}{\tau_m N^2} \; \Bigl| \; \frac{\mathtt a_m}{4} \log_b (\mathtt s_m) < N  \Bigr\} \leq   \frac{C_0 \mathtt K_m^2}{\tau_m \mathtt a_m \log_b(\mathtt s_m)} \nonumber \\ &\leq C_0 \frac{\sigma_{1m}}{\beta_{1m}} \frac{\mathtt K_m^2}{\log_b (\mathtt s_m)} \mathtt s_m^{-\mathtt K_m^2} \leq C(b) \mathtt K_m^2 \mathtt s_m^{-\mathtt K_m^2} \leq C(b, \pmb{\Pi}) 2^{-c_0 \mathtt K_m^2}. \label{Y2-final-1} 
\end{align}

\begin{align} 
\mathcal Y_{2}'' &\leq \sum_{u, v, N} \Biggl\{\frac{1}{N^3}\bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| \; \; \Biggl| \; \; \begin{aligned} &  \mathtt k(u) + \mathtt h >  \mathtt b_m, \; v \in \mathbb Z_N, \\  &N > \frac{\mathtt a_m}{4} \log_b (\mathtt s_m)\end{aligned} \Biggr\} \nonumber \\ 
&\leq C_0 \sum_{u, v, N}  \Biggl\{\frac{1}{N^3} \frac{\mathtt s_m^{\mathtt b_m}}{|h|b^{u+v}} \; \; \Biggl| \; \; \begin{aligned} &  u\tau_m >  \mathtt b_m - \mathtt h, \; v \in \mathbb Z_N, \\  &N > \frac{\mathtt a_m}{4} \log_b (\mathtt s_m)  \end{aligned} \Biggr\} \nonumber \\ 
&\leq C(h, b) \sum_{u, N} \Bigl\{ \frac{\mathtt s_m^{\mathtt b_m}}{N^3} b^{-u} \; \Bigl| \; u\tau_m >  \mathtt b_m - \mathtt h, \; N > \frac{\mathtt a_m}{4} \log_b (\mathtt s_m)  \Bigr\} \label{Y2-intermediate} \\ 
&\leq C(h, b) \mathtt s_m^{\mathtt b_m} b^{- \lfloor(\mathtt b_m - \mathtt h)/\tau_m \rfloor} \sum_N \Bigl\{N^{-3} | N > \frac{\mathtt a_m}{4}  \log_b (\mathtt s_m) \Bigr\} \nonumber \\  
& \leq C(h, b) \bigl[\mathtt s_m^{\mathtt b_m} b^{-\mathtt b_m /\tau_m} \bigr] \times b^{\mathtt h/\tau_m} \times \sum_N \Bigl\{N^{-3} | N > \frac{\mathtt a_m}{4}  \log_b (\mathtt s_m) \Bigr\} \nonumber  \\ 
&\leq C(h, b) \mathtt s_m^{\mathtt K_m} \bigl[ \mathtt a_m \log_b (\mathtt s_m) \bigr]^{-2}  \leq C(h, b) \mathtt s_m^{- c_0 \mathtt K_m^2} \text{ for some } c_0 > 0. \label{Y2-final-2}
\end{align}

\begin{equation} \label{Y2-final} 
\mathcal Y_2 \leq C(h, b, \pmb{\Pi}) 2^{-c_0 \mathtt K_m^2}.
\end{equation}

\begin{align} 
&\overline{\mathbb{\mathbb V}}_{23} \subseteq \bigl\{(u, v, N) \in \mathbb V_2 : u \in \mathbb E(|\xi(h,v)|, R, 0) \bigr\} \text{ with $\xi$ as in \eqref{new-xi}; as a result } \nonumber \\ 
&\# \bigl[ \pi_N \bigl( \overline{\mathbb V}_{23}\bigr) \bigr] \leq  N \sup_{v} \#\bigl[ \mathbb E(|\xi(h,v)|, R, 0) \bigr] \nonumber \\ &\hskip0.75in \leq C_0  {N}\kappa_m^{-1} 2^{-\frac{R}{4}} \log_2 (\mathtt s_m) \mathtt s_m^R b^{2 \mathtt s_m} \bigl(|\xi(h,v)|\bigr)_{\mathtt p_1} \nonumber \\
&\hskip0.75in \leq C(h) {N} \kappa_m^{-1} 2^{-\frac{R}{4}} \log_2 (\mathtt s_m) \mathtt s_m^R b^{2 \mathtt s_m}, \label{cardinality-V23-bar} 
\end{align}

\begin{align*}
& \mathtt p_1 \mid b^v \text{ for all } v \in \mathbb N, \text{ which means } \mathtt p_1 \nmid (b^v-1), \text{ i.e. } (b^v-1)_{\mathtt p_1} = 1, \; \text{ and therefore } \\
&\bigl( |\xi(h,v)|\bigr)_{\mathtt p_1} = \bigl({|(h)'_{\mathtt s}|}(b^v-1)\bigr)_{\mathtt p_1} = ({|(h)'_{\mathtt s}|})_{\mathtt p_1}  (b^v-1)_{\mathtt p_1} \leq |(h)'_{\mathtt s}| \leq |h|. 
\end{align*}

\begin{align} 
\mathcal Y_3 &= \sum_{u,v, N} \Bigl\{\frac{1}{N^3}\bigl| \mathtt v_m \bigl(hb^u(b^v-1) \bigr) \bigr| \; \Bigl| \; (u, v, N) \in \overline{\mathbb V}_{23} \Bigr\} \leq C_0 \sum_{N} N^{-3} \# \bigl[\pi_N \bigl(\overline{\mathbb V}_{23} \bigr) \bigr] \nonumber \\ 
&\leq C_0 \sum_N \Bigl\{\frac{1}{N^2} \kappa_m^{-1} 2^{-\frac{R}{4}} \log_2 (\mathtt s_m) \mathtt s_m^R b^{2 \mathtt s_m} \; \Bigr| \; N > \frac{\mathtt a_m}{4} \log_2(\mathtt s_m) \Bigr\} \nonumber \\
&\leq C(h) \bigl[ \mathtt a_m \log_b(\mathtt s_m) \bigr]^{-1} \kappa_m^{-1} 2^{-c_0 \mathtt K_m^2} \log_2(\mathtt s_m) b^{2 \mathtt s_m} \leq C(h, b) 2^{-{c} \mathtt K_m^2}, \label{Y3-final}
\end{align}

\begin{equation} \label{R-ku-h-inclusion} 

\{1, 2, \ldots, R\} \subseteq \bigl\{\mathtt K_m - \mathtt k(u) - \mathtt h, \ldots, \mathtt b_m - \mathtt k(u) - \mathtt h \bigr\}.  
\end{equation}

\begin{align*} 
\mathtt J &\bigl(h b^u(b^v-1); \, \mathtt s_m, \mathtt K_m, \mathtt b_m \bigr) \\  &:= \#\bigl\{\mathtt K_m - \mathtt k(u) - \mathtt h \leq j \leq \mathtt b_m -\mathtt k(u) - \mathtt h -1 : 1 \leq \mathtt d_{j-1}(|\zeta|) + \mathtt s \mathtt d_j(|\zeta|) \leq \mathtt s_m^2-2 \bigr\}  \\
&\geq \#\bigl\{1 \leq j \leq R-1: 1 \leq \mathtt d_{j-1}(|\zeta|) + \mathtt s_m \mathtt d_j(|\zeta|) \leq \mathtt s_m^2-2 \bigr\}\\ 
& = \mathfrak n_{R} \bigl(\mathbf d_R(u; {|\xi|}, b, \mathtt s_m), \mathtt s_m\bigr) > \kappa_m R, 
\end{align*}

\begin{align}
\mathcal Y_4 &= \sum_{u, v, N} \Bigl\{\frac{1}{N^3}\bigl| \mathtt v_m \bigl( hb^u(b^v-1) \bigr) \bigr| \; \Bigl| \; (u, v, N) \in \overline{\mathbb V}_{24} \Bigr\} \nonumber \\ 
&\leq C_0 \sum_{u, v, N} \Biggl\{ \frac{1}{N^3} \Bigl[ \frac{\mathtt s_m^{\mathtt a_m - \mathtt K_m}}{\mathtt N_m} + \Bigl( 1 - \frac{c_0}{\mathtt s_m^5}\Bigr)^{\kappa_m R} \Bigr] \; \Biggl| \; \begin{aligned} &(u, v) \in \mathbb Z_N^2, \\ &\frac{\mathtt a_m}{4}  {\log_b (\mathtt s_m) } < N < m \mathtt b_m \log_b(\mathtt s_m) \end{aligned} \Biggr\} \nonumber \\
&\leq C_0 \sum_{N, R} \Biggl\{\frac{1}{N} \Bigl[ \frac{\mathtt s_{m-1}^{\mathtt b_{m-1}}}{\mathtt s_m^{\mathtt K_m}} + \Bigl( 1 - \frac{c_0}{\mathtt s_m^5}\Bigr)^{\kappa_m R}\Bigr] \; \Biggl| \; \begin{aligned} &\mathtt s_m^{R-1} \leq N < \mathtt s_m^R \\  &\frac{\mathtt K_m^2}{2} < R < 2\mathtt K_m^2 \end{aligned} \Biggr\} \nonumber \\
&\leq C_0 {\log(\mathtt s_m)} \sum_{R} \Bigl\{\frac{\mathtt s_{m-1}^{\mathtt b_{m-1}}}{\mathtt s_m^{\mathtt K_m}} + \Bigl( 1 - \frac{c_0}{\mathtt s_m^5}\Bigr)^{\kappa_m R} \; \Bigl| \; \frac{\mathtt K_m^2}{2} < R < 2\mathtt K_m^2 \Bigr\} \nonumber \\
&\leq C_0 {\log(\mathtt s_m)} \Bigl[ \mathtt K_m^2 \frac{\mathtt s_{m-1}^{\mathtt b_{m-1}}}{\mathtt s_m^{\mathtt K_m}} + \kappa_m^{-1} \mathtt s_m^5 \Bigl( 1 - \frac{c_0}{\mathtt s_m^5}\Bigr)^{\kappa_m \mathtt K_m^2/4} \Bigr] \leq C_0 2^{-c_0 \mathtt K_m}.  \label{Y4-final}
\end{align}
